# 판정기준51 흐름도 — CAD(여섯 방향 깎기) ↔ 칸(3D 칸 모델) 번갈아 고치기 · 마지막은 CAD · 10-15 사용자 「나>가>나>가 피드백 루프 · 각각의 장단점을 커버」
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
plt.rcParams["font.family"] = "Malgun Gothic"; f, a = plt.subplots(figsize=(20, 12.5)); a.axis("off"); a.set_xlim(0, 20); a.set_ylim(0, 12.5)
def 상자(x, y, w, h, t, c, s=13): a.add_patch(plt.Rectangle((x, y), w, h, fc=c, ec="k", lw=1.5)); a.text(x + w / 2, y + h / 2, t, ha="center", va="center", fontsize=s, linespacing=1.5)
def 화(x0, y0, x1, y1, c="k", t=None): a.annotate("", (x1, y1), (x0, y0), arrowprops=dict(arrowstyle="->", lw=2.5, color=c)); t and a.text((x0 + x1) / 2, (y0 + y1) / 2 + .25, t, ha="center", fontsize=12, color=c)
상자(.3, 9.6, 3.9, 2.4, "0 · 정답 감사\n부서진 정답 29 개 등\n표시해 따로 센다", "#f6c6c6")
상자(.3, 6.6, 3.9, 2.6, "1 · CAD 천장 (학습 없음)\n정답 여섯 방향 깊이 → CadQuery\n712 개 · 새 채점기\n≥ 0.80 이어야 루프로 감", "#d8ecd8")
상자(.3, 3.6, 3.9, 2.6, "2 · 데이터 (학습 8,997)\n여섯 방향 칠 + 깊이 · 정답 칸 48³\n다섯 묶음으로 나눔\n(앞 판 결과는 그 묶음을\n안 본 모델로 채움)", "#ddd")
화(2.25, 9.6, 2.25, 9.2); 화(2.25, 6.6, 2.25, 6.2)
# 루프
